<script setup lang="ts">
import PipelineRolloutPreview from '@/components/PipelineRolloutPreview.vue';
import {computed,shallowRef,nextTick,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {message,Modal} from 'ant-design-vue';
import {usePermission} from '@/composables/permission';
import {listPipelines,listPipelineVersions,getPipeline,createPipeline,updatePipeline,setPipelineAvailability,createPipelineTask,createPipelineRolloutTask,publishPipeline,getPublicationGate,type GateDecision,type PublicationEvidence,type PipelineAsset,type PipelineRelease,type PipelineTaskRequest} from '@/api/pipelines';
import {pipelinePayloadRestricted,type PublishedPipeline,type PipelineVersion} from '@/api/pipeline-policies';
import {getTask,runTask,listTaskExecutions,type TaskExecutionSummary,type InspectionTask} from '@/api/tasks';
import SelectorEditor from '@/components/SelectorEditor.vue';
import SelectorAssetLibrary from '@/components/SelectorAssetLibrary.vue';
import type {SelectorAssetReference} from '@/api/selectors';
import {selectorJsonNeedsExactEditor} from '@/api/selectors';
import ConversationPicker from '@/components/ConversationPicker.vue';
import ReviewTaskSelector from '@/components/ReviewTaskSelector.vue';
import PipelineReleaseEditor from '@/components/PipelineReleaseEditor.vue';
const {can}=usePermission();
const rows=ref<PublishedPipeline[]>([]),total=ref(0),current=ref(1),loading=ref(false),error=ref(''),busy=ref(false),open=ref(false),selected=ref<PipelineAsset>();
const code=ref(''),name=ref(''),initial=ref<PipelineRelease>(),editor=ref<InstanceType<typeof PipelineReleaseEditor>>(),editorKey=ref(0),baseline=ref('');
const payloadRestricted=ref(false);
const history=ref<PipelineVersion[]>([]),historyLoading=ref(false),historyError=ref('');
const taskKind=ref<'TRIAL'|'PUBLISHED'|'ROLLOUT'>('TRIAL'),version=ref<number>(),taskName=ref(''),conversations=ref<string[]>([]),concurrency=ref(1),createdTask=ref<InspectionTask>(),taskError=ref('');
const selectionMode=ref<'MANUAL'|'SELECTOR'|'ASSET'>('MANUAL'),selectorEditor=ref<InstanceType<typeof SelectorEditor>>();
const bulkEnabled=ref(false),bulkScanSize=ref(1000);
watch([taskKind,selectionMode,()=>can('iqc:task:execute')],()=>{if(taskKind.value!=='PUBLISHED'||selectionMode.value!=='SELECTOR'||!can('iqc:task:execute'))bulkEnabled.value=false;});
watch(taskKind,kind=>{if(kind==='ROLLOUT'&&selectionMode.value==='SELECTOR')selectionMode.value='MANUAL';},{flush:'sync'});
const selectorAsset=ref<SelectorAssetReference>(),selectorAssetLabel=ref('');
function chooseSelector(reference:SelectorAssetReference,label:string){if(busy.value||command.value)return;selectorAsset.value={...reference};selectorAssetLabel.value=label;selectionMode.value='ASSET';}
const command=ref<{assetId:string;trial:boolean;rollout?:boolean;body:PipelineTaskRequest}>();
const qualityTaskId=ref(''),regressionTaskId=ref(''),qualityExecutionId=ref<string>(),regressionExecutionId=ref<string>(),qualityRounds=ref<TaskExecutionSummary[]>([]),regressionRounds=ref<TaskExecutionSummary[]>([]),gate=shallowRef<GateDecision>(),gateBusy=ref(false),gateError=ref(''),forceReason=ref('');let qualityGeneration=0,regressionGeneration=0,gateGeneration=0;
const trialTaskId=ref(''),trialStatus=ref(''),reviewed=ref(false),startUncertain=ref(false);
watch(trialTaskId,()=>{trialStatus.value='';reviewed.value=false;});
function invalidateGate(){++gateGeneration;gate.value=undefined;gateBusy.value=false;gateError.value='';}
watch([qualityTaskId,qualityExecutionId,regressionTaskId,regressionExecutionId,()=>selected.value?.id,()=>selected.value?.draftRevision],invalidateGate);
async function evidenceRounds(kind:'QUALITY'|'REGRESSION',id:string){const quality=kind==='QUALITY',ticket=quality?++qualityGeneration:++regressionGeneration,assetId=selected.value?.id;if(quality){qualityRounds.value=[];qualityExecutionId.value=undefined;}else{regressionRounds.value=[];regressionExecutionId.value=undefined;}if(disposed||!can('iqc:task:executions:view')||!id.trim())return;try{const rows=await listTaskExecutions(id.trim());if(disposed||!can('iqc:task:executions:view')||ticket!==(quality?qualityGeneration:regressionGeneration)||assetId!==selected.value?.id)return;const terminal=rows.filter(r=>['SUCCEEDED','PARTIAL_FAILED','FAILED','CANCELLED'].includes(r.status));if(quality){qualityRounds.value=terminal;qualityExecutionId.value=terminal[0]?.id;}else{regressionRounds.value=terminal;regressionExecutionId.value=terminal[0]?.id;}}catch{if(ticket===(quality?qualityGeneration:regressionGeneration))gateError.value='评测执行历史加载失败，请核对任务权限。';}}
watch(qualityTaskId,id=>void evidenceRounds('QUALITY',id));watch(regressionTaskId,id=>void evidenceRounds('REGRESSION',id));
function publicationEvidence():PublicationEvidence{if(!qualityTaskId.value.trim()||!regressionTaskId.value.trim()||!qualityExecutionId.value||!regressionExecutionId.value)throw Error('请选择质量与回归评测的终态执行轮次');return {qualityEvidence:{taskId:qualityTaskId.value.trim(),executionId:qualityExecutionId.value},regressionEvidence:{taskId:regressionTaskId.value.trim(),executionId:regressionExecutionId.value}};}
async function previewGate(){const asset=selected.value;if(!asset||dirty.value||gateBusy.value||!can('iqc:pipeline:gate:view'))return;let evidence:PublicationEvidence;try{evidence=publicationEvidence();}catch(e){message.warning(e instanceof Error?e.message:'请补齐评测');return;}const ticket=++gateGeneration;gate.value=undefined;gateBusy.value=true;gateError.value='';try{const decision=await getPublicationGate(asset.id,asset.draftRevision,evidence);if(ticket===gateGeneration&&selected.value?.id===asset.id&&selected.value.draftRevision===asset.draftRevision)gate.value=decision;}catch{if(ticket===gateGeneration)gateError.value='准入报告未获得，请核对评测来源、完整产物及精确冻结配置。';}finally{if(ticket===gateGeneration)gateBusy.value=false;}}
let generation=0,historyGeneration=0,detailGeneration=0,statusGeneration=0,disposed=false;
function taskSummary(task:InspectionTask):InspectionTask{return {id:task.id,name:task.name,status:task.status,taskType:task.taskType,concurrencyLimit:task.concurrencyLimit,totalMessages:task.totalMessages,processedMessages:task.processedMessages,failedMessages:task.failedMessages,taskPresentation:task.taskPresentation};}
const fresh=():PipelineRelease=>({schemaVersion:'iqc-pipeline-release-v1',pipeline:{schemaVersion:'iqc-pipeline-v1',nodes:[]},fusion:{id:'DEFAULT',version:1,method:'PRIORITY',nodePriority:{},overrideNodeByCode:{},confidenceCalibrationId:null,calibratedNodeIds:[]},scoring:{version:'iqc-score-v2',mode:'DEDUCTION',baseScore:100,passingScore:60,items:[]},items:[]});
const writable=computed(()=>!payloadRestricted.value&&(selected.value?can('iqc:pipeline:update'):can('iqc:pipeline:manage')));
const dirty=computed(()=>{if(payloadRestricted.value)return false;if(!selected.value)return true;try{return JSON.stringify([name.value,editor.value?.release()])!==baseline.value;}catch{return true;}});
function resetTask(){bulkEnabled.value=false;bulkScanSize.value=1000;++qualityGeneration;++regressionGeneration;qualityTaskId.value='';regressionTaskId.value='';qualityRounds.value=[];regressionRounds.value=[];qualityExecutionId.value=undefined;regressionExecutionId.value=undefined;forceReason.value='';invalidateGate();command.value=undefined;taskError.value='';createdTask.value=undefined;conversations.value=[];selectionMode.value='MANUAL';taskName.value='';trialTaskId.value='';trialStatus.value='';reviewed.value=false;version.value=undefined;taskKind.value=can('iqc:pipeline:execute')?'TRIAL':'PUBLISHED';concurrency.value=1;startUncertain.value=false;history.value=[];historyError.value='';historyLoading.value=false;++historyGeneration;}
async function refresh(page=current.value){if(!can('iqc:pipeline:view'))return;const ticket=++generation;loading.value=true;error.value='';current.value=page;try{const data=await listPipelines(page);if(ticket===generation){rows.value=data.records;total.value=data.total;}}catch{if(ticket===generation){rows.value=[];error.value='流水线目录加载失败，请重试。';}}finally{if(ticket===generation)loading.value=false;}}
function create(){if(busy.value)return;++detailGeneration;payloadRestricted.value=false;selected.value=undefined;code.value='';name.value='';initial.value=fresh();editorKey.value++;baseline.value='';resetTask();open.value=true;}
function restrictDraft(){history.value=[];++historyGeneration;invalidateGate();payloadRestricted.value=true;initial.value=undefined;baseline.value='';editorKey.value++;if(taskKind.value==='TRIAL')taskKind.value='PUBLISHED';}
function applyReceipt(asset:PipelineAsset){
 selected.value=asset;name.value=asset.name;
 const p=asset.privacy;
 if(p&&(p.policyVersion!=='iqc-pipeline-read-v1'||!p.canReadFull||!p.canReadPii||!p.canReadPrompt))restrictDraft();
}
async function load(row:{id:string}){
 if(busy.value||!can('iqc:pipeline:detail:view'))return;
 const ticket=++detailGeneration;busy.value=true;initial.value=undefined;selected.value=undefined;name.value='';code.value='';baseline.value='';resetTask();
 try{
  const asset=await getPipeline(row.id);if(disposed||ticket!==detailGeneration)return;
  selected.value=asset;code.value=asset.code;name.value=asset.name;payloadRestricted.value=pipelinePayloadRestricted(asset);
  if(payloadRestricted.value){restrictDraft();open.value=true;return;}
  if(!asset.draftConfigJson)throw Error();
  if(selectorJsonNeedsExactEditor(asset.draftConfigJson)){restrictDraft();open.value=true;message.warning('草稿包含此编辑器无法精确保存的数值，暂无法打开编辑，避免保存时舍入。');return;}
  const release=JSON.parse(asset.draftConfigJson) as PipelineRelease;
  if(release.schemaVersion!=='iqc-pipeline-release-v1'||!['iqc-pipeline-v1','iqc-pipeline-parallel-v1','iqc-pipeline-parallel-v2'].includes(release.pipeline?.schemaVersion)||(release.pipeline.schemaVersion==='iqc-pipeline-parallel-v2'?!release.pipeline.completionPolicy:release.pipeline.completionPolicy!=null)||!Array.isArray(release.pipeline.nodes)||!release.fusion||!release.scoring||!Array.isArray(release.items))throw Error();
  initial.value=release;editorKey.value++;open.value=true;await nextTick();if(disposed||ticket!==detailGeneration)return;baseline.value=JSON.stringify([name.value,editor.value?.release()]);
 }catch{if(!disposed&&ticket===detailGeneration){restrictDraft();message.error('流水线加载失败或快照格式无效。');}}
 finally{if(!disposed&&ticket===detailGeneration)busy.value=false;}
}
function reload(){if(!selected.value||busy.value)return;const row=selected.value;if(dirty.value)Modal.confirm({title:'重新加载草稿？',content:'未保存的编辑内容将被替换。',onOk:()=>load(row)});else void load(row);}
async function save(){if(busy.value||!writable.value||!editor.value)return;let release:PipelineRelease;try{release=editor.value.release();if(!name.value.trim()||name.value.length>100||!selected.value&&!/^[A-Z][A-Z0-9_]{1,63}$/.test(code.value))throw Error('请填写名称与稳定编码');}catch(e){message.error(e instanceof Error?e.message:'配置无效');return;}busy.value=true;try{const asset=selected.value?await updatePipeline(selected.value.id,selected.value.draftRevision,name.value,release):await createPipeline(code.value,name.value,release);if(disposed)return;applyReceipt(asset);name.value=asset.name;if(!payloadRestricted.value)baseline.value=JSON.stringify([name.value,release]);trialTaskId.value='';trialStatus.value='';reviewed.value=false;invalidateGate();message.success('草稿已保存，请以新修订重新核对评测证据');await refresh();}catch{message.error('保存未成功。请保留编辑内容并重新加载核对修订、引用资产及配置。');}finally{busy.value=false;}}
async function versions(){if(!selected.value||!can('iqc:pipeline:versions:view'))return;const ticket=++historyGeneration,id=selected.value.id;historyLoading.value=true;historyError.value='';history.value=[];try{const data=await listPipelineVersions(id);if(ticket===historyGeneration)history.value=data;}catch{if(ticket===historyGeneration)historyError.value='发布历史加载失败，请重试。';}finally{if(ticket===historyGeneration)historyLoading.value=false;}}
function availability(row:PublishedPipeline){if(busy.value)return;const enabled=row.status!=='ACTIVE';Modal.confirm({title:`${enabled?'启用':'停用'} ${row.name}？`,content:enabled?'允许使用该流水线。':'引用此流水线的任务将在执行可用性检查时被阻止。',async onOk(){busy.value=true;try{const asset=await setPipelineAvailability(row.id,enabled);if(disposed)return;if(selected.value?.id===asset.id)applyReceipt(asset);await refresh();}catch{message.error('设置失败，请刷新核对。');}finally{busy.value=false;}}});}
async function executeCommand(){if(disposed||!command.value||busy.value)return;const pending=command.value;busy.value=true;taskError.value='';try{const task=pending.rollout?await createPipelineRolloutTask(pending.assetId,{name:pending.body.name,...(pending.body.selectorAsset?{selectorAsset:{...pending.body.selectorAsset}}:{conversationIds:pending.body.conversationIds??[]}),concurrency:pending.body.concurrency,requestKey:pending.body.requestId!}):await createPipelineTask(pending.assetId,pending.trial,pending.body);if(disposed||command.value!==pending)return;createdTask.value=taskSummary(task);command.value=undefined;if(pending.trial){trialTaskId.value=task.id;trialStatus.value=task.status;}message.success(task.status==='CREATED'?'任务已创建或找到原任务，尚未开始执行':'已找到原任务，保留原执行状态');}catch{if(!disposed&&command.value===pending)taskError.value='创建结果未确认，请使用原请求重试。';}finally{if(!disposed)busy.value=false;}}
function stopRetry(){if(!command.value||busy.value)return;Modal.confirm({title:'停止重试本次创建？',content:'请先到任务列表核对请求是否已创建任务，再创建新的任务。',onOk(){command.value=undefined;taskError.value='';}});}
function createTask(){
 if(!selected.value||busy.value||command.value||!taskName.value.trim()||selected.value.status!=='ACTIVE')return;
 const trial=taskKind.value==='TRIAL',rollout=taskKind.value==='ROLLOUT';
 if(rollout&&selectionMode.value==='SELECTOR'){message.warning('灰度任务请选择会话或已发布选择器');return;}
 if(trial&&(payloadRestricted.value||dirty.value)){message.warning('请先保存草稿');return;}
 if(!trial&&!rollout&&!version.value){message.warning('请选择发布版本');return;}
 if(!can(trial?'iqc:pipeline:execute':'iqc:pipeline:task:create')||rollout&&!can('iqc:pipeline:rollout:task:create'))return;
 let selection:Pick<PipelineTaskRequest,'conversationIds'|'selector'|'selectorAsset'>;
 try{if(!trial&&selectionMode.value==='ASSET'){
  if(!selectorAsset.value)throw Error('请在已保存的会话选择器中选择发布版本');selection={selectorAsset:{...selectorAsset.value}};
 }else if(!trial&&!rollout&&selectionMode.value==='SELECTOR'){
  if(!selectorEditor.value)throw Error('选择器尚未就绪');selection={selector:selectorEditor.value.definition()};
 }else{if(!conversations.value.length)throw Error('请选择会话');selection={conversationIds:[...conversations.value]};}}
 catch(e){message.warning(e instanceof Error?e.message:'选择器无效');return;}
 if(bulkEnabled.value&&(trial||rollout||selectionMode.value!=='SELECTOR'||!selection.selector||selection.selector.sampling.mode!=='ALL'||!can('iqc:task:execute')||!Number.isInteger(bulkScanSize.value)||bulkScanSize.value<1||bulkScanSize.value>selection.selector.maximumCount)){message.warning('分片批次需使用ALL选择器，每片大小不能超过选择器上限，并具备任务执行权限');return;}
 command.value={assetId:selected.value.id,trial,rollout,body:{name:taskName.value.trim(),...selection,...(bulkEnabled.value?{bulk:{scanSize:bulkScanSize.value}}:{}),requestId:crypto.randomUUID(),
  ...(trial?{expectedRevision:selected.value.draftRevision}:{...(rollout?{}:{versionNo:version.value}),concurrency:concurrency.value})}};
 void executeCommand();
}
async function start(){const task=createdTask.value;if(!task||busy.value||startUncertain.value||task.status!=='CREATED'||!can('iqc:task:execute'))return;busy.value=true;try{createdTask.value=taskSummary(await runTask(task.id));if(trialTaskId.value===task.id)trialStatus.value=createdTask.value.status;}catch{startUncertain.value=true;message.error('执行请求未确认，请刷新任务状态后操作。');}finally{busy.value=false;}}
async function taskStatus(trial=false){
 if(disposed||!can('iqc:task:detail:view')||busy.value)return;
 const id=trial?trialTaskId.value:createdTask.value?.id;if(!id)return;
 const ticket=++statusGeneration,context=detailGeneration;busy.value=true;
 try{const task=await getTask(id);if(disposed||ticket!==statusGeneration||context!==detailGeneration||!can('iqc:task:detail:view'))return;
  if(createdTask.value?.id===id){createdTask.value=taskSummary(task);startUncertain.value=false;}
  if(trialTaskId.value===id)trialStatus.value=task.status;
 }catch{if(!disposed&&ticket===statusGeneration)message.error('任务状态加载失败');}finally{busy.value=false;}
}
function publish(force=false){const asset=selected.value;if(!asset||busy.value||dirty.value||!trialTaskId.value||!reviewed.value||!gate.value||!can(force?'iqc:pipeline:force:publish':'iqc:pipeline:publish')||!force&&!gate.value.passed)return;let evidence:PublicationEvidence;try{evidence=publicationEvidence();}catch{return;}const reason=forceReason.value.trim();if(force&&!reason){message.warning('管理员例外必须填写原因');return;}const trialId=trialTaskId.value,encoded=JSON.stringify(evidence);Modal.confirm({title:`${force?'管理员例外发布':'发布'} ${asset.name} 草稿修订 ${asset.draftRevision}？`,content:force?'未通过的准入项、测量报告和例外原因将保存到不可变版本与审计。':'服务端重新检查试跑、冻结内容与质量/回归阈值。',async onOk(){let currentEvidence:string;try{currentEvidence=JSON.stringify(publicationEvidence());}catch{message.warning('评测选择已变化，请重新核对');return;}if(selected.value?.id!==asset.id||selected.value.draftRevision!==asset.draftRevision||dirty.value||trialTaskId.value!==trialId||!reviewed.value||currentEvidence!==encoded){message.warning('发布选择已变化，请重新核对');return;}busy.value=true;try{await publishPipeline(asset.id,asset.draftRevision,trialId,true,{...evidence,...(force?{forceReason:reason}:{})},force);const refreshed=await getPipeline(asset.id);if(disposed)return;applyReceipt(refreshed);if(pipelinePayloadRestricted(refreshed))restrictDraft();message.success(force?'管理员例外发布已保存并审计':'不可变版本已通过准入并发布');await versions();await refresh();}catch{message.error('发布未成功，请重新核对试跑、测量准入及管理员权限。');}finally{busy.value=false;}}});}
function pretty(raw:string|null){try{return raw?JSON.stringify(JSON.parse(raw),null,2):'正文未提供';}catch{return '版本快照格式无效';}}
watch(open,value=>{if(!value){++detailGeneration;initial.value=undefined;selected.value=undefined;name.value='';code.value='';baseline.value='';payloadRestricted.value=false;resetTask();}});
// Navigation invalidates pending creation receipts without changing the server task.
watch(()=>[can('iqc:task:detail:view'),can('iqc:task:executions:view'),can('iqc:sensitive:conversation:read'),can('iqc:sensitive:pii:read'),can('iqc:sensitive:prompt:read')],()=>{
 ++statusGeneration;++qualityGeneration;++regressionGeneration;trialStatus.value='';reviewed.value=false;qualityRounds.value=[];regressionRounds.value=[];qualityExecutionId.value=undefined;regressionExecutionId.value=undefined;invalidateGate();
 if(can('iqc:task:executions:view')&&open.value){void evidenceRounds('QUALITY',qualityTaskId.value);void evidenceRounds('REGRESSION',regressionTaskId.value);}
},{flush:'sync'});
onMounted(()=>void refresh());onBeforeUnmount(()=>{disposed=true;++detailGeneration;initial.value=undefined;selected.value=undefined;history.value=[];name.value='';command.value=undefined;++generation;++historyGeneration;++qualityGeneration;++regressionGeneration;++gateGeneration;});
</script>
<template>
<section class="page-intro"><div><h2>检测流水线</h2><p>配置版本化检测节点、事实融合和评分映射，真实试跑后发布。</p></div><a-button v-if="can('iqc:pipeline:manage')" type="primary" :disabled="busy" @click="create">新建流水线</a-button></section>
<a-alert v-if="error" type="error" :message="error" show-icon/><a-button :loading="loading" @click="refresh()">刷新目录</a-button>
<a-table :data-source="rows" row-key="id" :loading="loading" :pagination="false" :scroll="{x:850}"><a-table-column title="编码" data-index="code"/><a-table-column title="名称" data-index="name"/><a-table-column title="可用性" data-index="status"/><a-table-column title="发布版本"><template #default="{record}">{{record.activePublishedVersion==null?'未发布':`v${record.activePublishedVersion}`}}</template></a-table-column><a-table-column title="操作"><template #default="{record}"><a-space><a-button v-if="can('iqc:pipeline:detail:view')" type="link" :disabled="busy" @click="load(record)">查看 / 编辑</a-button><a-button v-if="can('iqc:pipeline:availability')" type="link" :disabled="busy" @click="availability(record)">{{record.status==='ACTIVE'?'停用':'启用'}}</a-button></a-space></template></a-table-column></a-table><a-pagination :current="current" :total="total" :page-size="20" :show-size-changer="false" @change="refresh"/>
<SelectorAssetLibrary :disabled="busy||!!command" @select="chooseSelector"/><a-alert v-if="selectorAsset" type="info" :message="`任务选数版本：${selectorAssetLabel}`"/>
<a-drawer v-model:open="open" :width="880" title="流水线配置与发布" :closable="!busy && !command" :mask-closable="!busy && !command" :keyboard="!busy && !command">
<a-form layout="vertical"><a-form-item label="稳定编码"><a-input v-model:value="code" :maxlength="64" :disabled="busy || !!selected || !writable"/></a-form-item><a-form-item label="名称"><a-input v-model:value="name" :maxlength="100" :disabled="busy || !!command || !writable"/></a-form-item></a-form>
<p v-if="selected">草稿修订 {{selected.draftRevision}} · {{selected.status}} · 当前发布 {{selected.activePublishedVersion ?? '无'}}</p>
<a-alert v-if="payloadRestricted" type="info" message="配置正文受限或不可精确编辑，未加载编辑器。请核对完整会话、PII、Prompt读取权限后重新加载；仍可使用已发布版本创建任务。"/>
<PipelineReleaseEditor v-if="initial && !payloadRestricted" :key="editorKey" ref="editor" :initial="initial" :disabled="busy || !!command || !writable"/>
<a-space><a-button v-if="writable" type="primary" :loading="busy" :disabled="!!command" @click="save">保存草稿</a-button><a-button v-if="selected" :disabled="busy || !!command" @click="reload">重新加载草稿</a-button></a-space><a-alert v-if="selected && dirty" type="info" message="有未保存修改，请保存后试跑或发布。"/>
<template v-if="selected"><h3>发布历史（最近100条）</h3><a-button v-if="can('iqc:pipeline:versions:view')" :loading="historyLoading" @click="versions">加载 / 刷新历史</a-button><a-alert v-if="historyError" type="error" :message="historyError"/><a-collapse><a-collapse-panel v-for="entry in history" :key="entry.id" :header="`v${entry.versionNo} · 草稿修订 ${entry.sourceDraftRevision}`"><p>{{entry.createdTime}} · {{entry.contentHash}}</p><a-alert v-if="pipelinePayloadRestricted(entry)" type="info" message="当前响应未提供版本正文及发布审计正文，请核对完整会话、PII、Prompt读取权限。"/><pre v-else>{{pretty(entry.snapshotJson)}}</pre><h4>发布准入与例外审计证据</h4><pre v-if="!pipelinePayloadRestricted(entry)&&entry.publicationDecisionJson">{{pretty(entry.publicationDecisionJson)}}</pre><p v-else-if="!pipelinePayloadRestricted(entry)">历史版本未记录该发布门禁证据。</p></a-collapse-panel></a-collapse>
<template v-if="can('iqc:selector:preview')&&!can('iqc:pipeline:execute')&&!can('iqc:pipeline:task:create')"><h3>会话选集预览</h3><p>可配置条件并查看当前数据分布。</p><SelectorEditor :disabled="busy"/></template>
<h3 v-if="can('iqc:pipeline:execute') || can('iqc:pipeline:task:create')">试跑与正式任务</h3>
<template v-if="can('iqc:pipeline:execute') || can('iqc:pipeline:task:create')"><a-form layout="vertical"><a-form-item label="任务方式"><a-select v-model:value="taskKind" :disabled="busy || !!command" :options="[{value:'TRIAL',label:'草稿试跑',disabled:payloadRestricted||!can('iqc:pipeline:execute')},{value:'PUBLISHED',label:'已发布版本任务',disabled:!can('iqc:pipeline:task:create')},{value:'ROLLOUT',label:'按已保存灰度策略分配',disabled:!can('iqc:pipeline:task:create')||!can('iqc:pipeline:rollout:task:create')}]"/></a-form-item><a-form-item v-if="taskKind==='PUBLISHED'" label="发布版本"><a-select v-model:value="version" :disabled="busy || !!command" :options="history.map(v=>({value:v.versionNo,label:`v${v.versionNo}`}))" placeholder="先加载发布历史"/></a-form-item><a-form-item label="任务名称"><a-input v-model:value="taskName" :maxlength="100" :disabled="busy || !!command"/></a-form-item><a-form-item v-if="taskKind!=='TRIAL'" label="并发"><a-input-number v-model:value="concurrency" :min="1" :max="32" :precision="0" :disabled="busy || !!command"/></a-form-item></a-form>
<a-alert v-if="taskKind==='ROLLOUT'" type="info" message="新请求使用服务端当前已保存策略；使用原请求重试会保留原任务及分配。首次选择器选数随任务冻结，原请求重试不重新选数。草稿和手动版本选择不参与。"/><a-radio-group v-if="taskKind==='PUBLISHED'||taskKind==='ROLLOUT'" v-model:value="selectionMode" :disabled="busy||!!command"><a-radio-button value="MANUAL">手动选择</a-radio-button><a-radio-button v-if="taskKind==='PUBLISHED'" value="SELECTOR">临时选择器</a-radio-button><a-radio-button v-if="can('iqc:selector:asset:version:view')" value="ASSET">已发布选择器</a-radio-button></a-radio-group><SelectorEditor v-if="taskKind==='PUBLISHED'&&selectionMode==='SELECTOR'" ref="selectorEditor" :disabled="busy||!!command"/><template v-else-if="(taskKind==='PUBLISHED'||taskKind==='ROLLOUT')&&selectionMode==='ASSET'"><SelectorAssetLibrary :disabled="busy||!!command" @select="chooseSelector"/><a-alert type="info" :message="selectorAsset?`使用 ${selectorAssetLabel}`:'请先在页面的已保存选择器目录中选择发布版本。'"/></template><template v-else><ConversationPicker v-if="can('iqc:conversation:view')" v-model="conversations" :key="taskKind" :max="taskKind==='TRIAL'?10:1000" :disabled="busy || !!command"/><a-alert v-else type="info" message="选择会话需要会话查看权限"/></template>
<template v-if="taskKind==='PUBLISHED'&&selectionMode==='SELECTOR'&&can('iqc:task:execute')"><a-form layout="vertical"><a-form-item label="全量分片批次"><a-switch v-model:checked="bulkEnabled" :disabled="busy||!!command"/></a-form-item><a-form-item v-if="bulkEnabled" label="每片候选会话数"><a-input-number v-model:value="bulkScanSize" :min="1" :max="1000" :precision="0" :disabled="busy||!!command"/></a-form-item></a-form><a-alert v-if="bulkEnabled" type="info" message="仅支持ALL选数。批次逐片冻结并执行，可暂停和恢复；扫描完成后仍需等待分片处理完成。创建时固定截止秒，截止秒及之后新增的会话留待后续批次。每片大小不能超过选择器上限。"/></template>
<a-button :disabled="busy || !!command || !taskName.trim() || ((taskKind==='TRIAL'||selectionMode==='MANUAL')&&!conversations.length) || (taskKind==='TRIAL' && (payloadRestricted || dirty || conversations.length>10)) || ((taskKind==='PUBLISHED'||taskKind==='ROLLOUT')&&selectionMode==='ASSET'&&!selectorAsset) || selected.status!=='ACTIVE'" @click="createTask">创建任务</a-button><a-alert v-if="taskError" type="warning" :message="taskError"/><a-space v-if="command"><a-button :loading="busy" @click="executeCommand">使用原请求重试</a-button><a-button :disabled="busy" @click="stopRetry">停止本次重试</a-button><RouterLink :to="{path:'/tasks'}" target="_blank">到任务列表核对</RouterLink></a-space>
<a-card v-if="createdTask" size="small"><p>{{createdTask.name}} · {{createdTask.id}} · {{createdTask.status}}</p><p v-if="createdTask.taskPresentation?.rollout?.schemaVersion==='iqc-rollout-presentation-v1'">灰度修订 r{{createdTask.taskPresentation.rollout.policyRevision}} · {{createdTask.taskPresentation.rollout.side==='CANDIDATE'?'候选':'基线'}} · 发布版本 v{{createdTask.taskPresentation.rollout.selectedVersionNo}}</p><a-space><a-button v-if="can('iqc:task:execute') && createdTask.status==='CREATED'" :disabled="busy || startUncertain" @click="start">开始执行</a-button><a-button v-if="can('iqc:task:detail:view')" :disabled="busy" @click="taskStatus(false)">刷新任务状态</a-button><RouterLink :to="{path:'/results',query:{taskId:createdTask.id}}">查看结果</RouterLink></a-space></a-card></template>
<template v-if="!payloadRestricted&&(can('iqc:pipeline:publish')||can('iqc:pipeline:gate:view')||can('iqc:pipeline:force:publish'))"><h3>发布确认</h3><ReviewTaskSelector v-model="trialTaskId" :disabled="busy"/><a-button v-if="can('iqc:task:detail:view')" :disabled="busy || !trialTaskId" @click="taskStatus(true)">核对试跑任务状态</a-button><p>试跑状态：{{trialStatus || '未核对'}}</p><RouterLink v-if="trialTaskId" :to="{path:'/results',query:{taskId:trialTaskId}}" target="_blank">查看试跑结果</RouterLink><p><a-checkbox v-model:checked="reviewed" :disabled="busy">我已查看该草稿修订的试跑结果</a-checkbox></p><h4>质量评测与回归评测证据</h4><p>请选择同一冻结流水线内容的两个评测Task/EID；回归必须来自REGRESSION数据集。需先保存并在评测中心运行。</p><RouterLink to="/evaluation/tasks" target="_blank">打开评测中心</RouterLink><a-form layout="vertical"><a-form-item label="质量评测任务"><ReviewTaskSelector v-model="qualityTaskId" task-type="PIPELINE_EVALUATION" :disabled="busy"/><a-select v-model:value="qualityExecutionId" :options="qualityRounds.map(r=>({value:r.id,label:`第 ${r.attemptNo} 轮 · ${r.status}`}))" placeholder="质量终态执行轮次" :disabled="busy" style="width:100%"/></a-form-item><a-form-item label="回归评测任务"><ReviewTaskSelector v-model="regressionTaskId" task-type="PIPELINE_EVALUATION" :disabled="busy"/><a-select v-model:value="regressionExecutionId" :options="regressionRounds.map(r=>({value:r.id,label:`第 ${r.attemptNo} 轮 · ${r.status}`}))" placeholder="回归终态执行轮次" :disabled="busy" style="width:100%"/></a-form-item></a-form><a-button v-if="can('iqc:pipeline:gate:view')" :loading="gateBusy" :disabled="busy||dirty||!qualityExecutionId||!regressionExecutionId" @click="previewGate">计算发布准入</a-button><a-alert v-if="gateError" type="warning" :message="gateError"/><template v-if="gate"><a-alert :type="gate.passed?'success':'warning'" :message="gate.passed?'测量准入通过；发布时再次校验':'测量准入未通过，普通发布已禁止'"/><a-table :data-source="gate.criteria" :row-key="(r:{purpose:string;code:string})=>`${r.purpose}:${r.code}`" :pagination="false"><a-table-column title="层级"><template #default="{record}">{{record.purpose==='QUALITY'?'质量':'回归'}}</template></a-table-column><a-table-column title="准入项"><template #default="{record}">{{({COMPLETE:'报告完整',MINIMUM_GOLD_SAMPLES:'最少金标样本',EXECUTION_SUCCESS:'执行成功样本',HIGH_RISK_RECALL:'高风险召回率',OVERALL_F1:'Overall F1',REGRESSION_PASS:'回归通过率',STRUCTURED_SUCCESS:'结构化输出成功率',P95_EVALUATOR_MS:'评测计算P95毫秒'} as Record<string,string>)[record.code]||record.code}}</template></a-table-column><a-table-column title="状态"><template #default="{record}">{{record.status==='PASSED'?'达标':record.status==='FAILED'?'未达标':'不适用'}}</template></a-table-column><a-table-column title="测量值" data-index="actual"/><a-table-column title="阈值" data-index="threshold"/><a-table-column title="原因" data-index="reason"/></a-table><details><summary>冻结发布准入证据</summary><pre>{{JSON.stringify(gate,null,2)}}</pre></details></template><a-button v-if="can('iqc:pipeline:publish')" type="primary" :disabled="busy || dirty || !trialTaskId || !reviewed || !gate?.passed || selected.status!=='ACTIVE'" @click="publish(false)">通过准入发布</a-button><template v-if="can('iqc:pipeline:force:publish')&&gate&&!gate.passed"><a-form-item label="管理员例外原因"><a-textarea v-model:value="forceReason" :maxlength="1000" :disabled="busy"/></a-form-item><a-button danger :disabled="busy||dirty||!trialTaskId||!reviewed||!forceReason.trim()||selected.status!=='ACTIVE'" @click="publish(true)">管理员例外发布并审计</a-button></template></template>
</template>
<PipelineRolloutPreview v-if="selected&&can('iqc:pipeline:rollout:preview')" :key="`rollout:${selected.id}`" :pipeline-id="selected.id" :disabled="busy"/>
</a-drawer>
</template>
<style scoped>.ant-pagination{margin-top:16px}.ant-alert{margin:12px 0}pre{max-height:300px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}</style>
